  // ---- Slope: a rise and a run ----
  "lines-and-slope.err.rr00": "A rise of 0 and a run of 0 don’t go anywhere — give a rise or a run that isn’t 0.",
  "lines-and-slope.rr.up": "Going up <b>{a}</b> is a rise of <b>{r}</b>",
  "lines-and-slope.rr.down": "Going down <b>{a}</b> is a rise of <b>{r}</b>",
  "lines-and-slope.rr.downNeg": " — down counts as negative.",
  "lines-and-slope.rr.noClimb": " — no climb at all.",
  "lines-and-slope.rr.right": "Going right <b>{a}</b> is a run of <b>{r}</b>",
  "lines-and-slope.rr.left": "Going left <b>{a}</b> is a run of <b>{r}</b>",
  "lines-and-slope.rr.leftNeg": " — left counts as negative.",
  "lines-and-slope.rr.noSide": " — no sideways move at all.",
  "lines-and-slope.rr.undef": "Slope is rise over run, <b>{f}</b> — but you can’t divide by 0, so the slope is <strong>undefined</strong>. No sideways move at all means a vertical line.",
  "lines-and-slope.rr.slope": "Slope is <strong>rise over run</strong>: <b>m = {f}</b>.",
  "lines-and-slope.rr.whyRR": "<strong>Why rise over run?</strong> Slope is how far the line climbs for every 1 step to the right — the rise divided by the run.",
  "lines-and-slope.rr.cap": "Start at {p}, go the <span class=\"kw c-e\">rise</span>, then the <span class=\"kw c-m\">run</span>, and you land on another point of the line.",
  "lines-and-slope.rr.aria": "Grid with a rise of {r} and a run of {u}",
  "lines-and-slope.rr.checkUndef": "<b>Check:</b> going straight up, the run stays 0 however far you climb — undefined every time{ok}",
  "lines-and-slope.rr.check": "<b>Check:</b> a bigger staircase on the same line gives the same slope. Twice as far — rise <b>{r2}</b>, run <b>{u2}</b> — gives <b>{f} = {m}</b>{ok} That’s why any two points on a line give the same slope.",
  "lines-and-slope.rr.word.up.right": "up {r}, right {u}",
  "lines-and-slope.rr.word.up.left": "up {r}, left {u}",
  "lines-and-slope.rr.word.down.right": "down {r}, right {u}",
  "lines-and-slope.rr.word.down.left": "down {r}, left {u}",
  "lines-and-slope.rr.ask.up.right": "A line goes up {r} and right {u}. What is its slope?",
  "lines-and-slope.rr.ask.up.left": "A line goes up {r} and left {u}. What is its slope?",
  "lines-and-slope.rr.ask.down.right": "A line goes down {r} and right {u}. What is its slope?",
  "lines-and-slope.rr.ask.down.left": "A line goes down {r} and left {u}. What is its slope?",
  "lines-and-slope.rr.askFrom.up.right": "A line goes up {r} and right {u} from {p}. What is its slope?",
  "lines-and-slope.rr.askFrom.up.left": "A line goes up {r} and left {u} from {p}. What is its slope?",
  "lines-and-slope.rr.askFrom.down.right": "A line goes down {r} and right {u} from {p}. What is its slope?",
  "lines-and-slope.rr.askFrom.down.left": "A line goes down {r} and left {u} from {p}. What is its slope?",
