  // ---- Parallel & perpendicular ----
  "lines-and-slope.par.given": "The given line",
  "lines-and-slope.tag.parallel": "Parallel",
  "lines-and-slope.par.same": "Parallel lines never meet: they go in exactly the same direction, so they have the <strong>same slope</strong>. ",
  "lines-and-slope.par.sameVert": "The given line is vertical, so the new one is vertical too.",
  "lines-and-slope.par.sameM": "The new line’s slope is <b>m = {m}</b> too.",
  "lines-and-slope.b.sameM": "same m",
  "lines-and-slope.tag.perp": "Perpendicular",
  "lines-and-slope.par.perpVert": "Perpendicular lines meet at a right angle. The given line is vertical, so a line at a right angle to it is flat — <strong>horizontal</strong>, slope <b>0</b>.",
  "lines-and-slope.par.perpFlat": "Perpendicular lines meet at a right angle. The given line is flat, so a line at a right angle to it goes straight up and down — <strong>vertical</strong>, undefined slope.",
  "lines-and-slope.par.asFrac": " ({m} is {f})",
  "lines-and-slope.par.recip": "Perpendicular lines meet at a right angle, and their slopes are <strong>negative reciprocals</strong>: flip the fraction upside down and change its sign. <b>{m0}</b>{asFrac} → flip it: <b>{flip}</b> → change the sign: <b>{m}</b>. Check: <b>{m0} · {mp} = −1</b> — perpendicular slopes always multiply to −1.",
  "lines-and-slope.par.why": "<strong>Why?</strong> Turn a staircase a quarter-turn and its rise and run swap places — and one of them changes direction. So rise/run becomes −run/rise.",
